cat > /app/submit/helper.c << 'EOF'
/* helper.c - native accelerator for the IPv6 pipeline compiler.
 *
 * Exported entry points:
 *   json_prescan : cheap structural pre-check of a raw request line
 *   find_cuts    : exact min-max utilisation cut placement (compile)
 *   utab         : debug helper, dumps the U(b,e) stage cost table
 *   lpm_batch    : longest prefix match for a batch of queries (lookup)
 *
 * Plain C (gnu11), libc only.
 */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct { uint64_t hi, lo; } u128;

#define MAXD 129

/* ------------------------------------------------------------------ */
/* JSON pre-scan                                                       */
/* ------------------------------------------------------------------ */

int json_prescan(const char *s, size_t len, long max_values, int max_depth,
                 long *out_values, int *out_depth)
{
    long values = 0;
    int depth = 0, maxd = 0, in_str = 0, esc = 0, in_num = 0;
    size_t i;
    for (i = 0; i < len; i++) {
        unsigned char c = (unsigned char)s[i];
        if (in_str) {
            if (esc) esc = 0;
            else if (c == '\\') esc = 1;
            else if (c == '"') in_str = 0;
            continue;
        }
        if (c == '"') { in_str = 1; in_num = 0; values++; }
        else if (c == '{' || c == '[') {
            in_num = 0; values++; depth++;
            if (depth > maxd) maxd = depth;
            if (depth > max_depth) {
                if (out_values) *out_values = values;
                if (out_depth) *out_depth = maxd;
                return 1;
            }
        }
        else if (c == '}' || c == ']') { in_num = 0; depth--; }
        else if (c == '-' || (c >= '0' && c <= '9')) { if (!in_num) { in_num = 1; values++; } }
        else if (c == 't' || c == 'f' || c == 'n') { in_num = 0; values++; }
        else if (c == '.' || c == '+' || c == 'e' || c == 'E' || c == '_' ||
                 (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
            /* inside a number or literal: nothing to count */
        }
        else { in_num = 0; }
        if (values > max_values) {
            if (out_values) *out_values = values;
            if (out_depth) *out_depth = maxd;
            return 1;
        }
    }
    if (out_values) *out_values = values;
    if (out_depth) *out_depth = maxd;
    return 0;
}

/* ------------------------------------------------------------------ */
/* 128 bit helpers                                                     */
/* ------------------------------------------------------------------ */

static int cmp_u128(const void *pa, const void *pb)
{
    const u128 *a = (const u128 *)pa, *b = (const u128 *)pb;
    if (a->hi < b->hi) return -1;
    if (a->hi > b->hi) return 1;
    if (a->lo < b->lo) return -1;
    if (a->lo > b->lo) return 1;
    return 0;
}

static inline u128 trunc128(u128 a, int d)
{
    if (d <= 0) { a.hi = 0; a.lo = 0; }
    else if (d < 64) { a.hi &= ~(((uint64_t)1 << (64 - d)) - 1); a.lo = 0; }
    else if (d == 64) { a.lo = 0; }
    else if (d < 128) { a.lo &= ~(((uint64_t)1 << (128 - d)) - 1); }
    return a;
}

static inline uint64_t align_up(uint64_t x, uint64_t k)
{
    uint64_t r = x % k;
    return r ? x + (k - r) : x;
}

static inline int rat_less(int64_t an, int64_t ad, int64_t bn, int64_t bd)
{
    __int128 l = (__int128)an * (__int128)bd;
    __int128 r = (__int128)bn * (__int128)ad;
    return l < r;
}

/* ------------------------------------------------------------------ */
/* canonical node layout per depth                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    int n;              /* number of prefixes */
    int m;              /* row stride of the node table (>= max(n,1)) */
    u128 *pk;           /* prefix addresses */
    const int32_t *lens;
    u128 *nodes;        /* MAXD * m : sorted distinct trunc(p,d) for len>d */
    int *ncnt;          /* MAXD */
    int *byLenOff;      /* MAXD+1 */
    int *byLen;         /* m prefix indices bucketed by length */
    int *byLenCnt;      /* MAXD */
} layout_t;

static void layout_free(layout_t *L)
{
    free(L->pk); free(L->nodes); free(L->ncnt);
    free(L->byLenOff); free(L->byLen); free(L->byLenCnt);
    memset(L, 0, sizeof(*L));
}

static int layout_build(layout_t *L, const uint64_t *addrs, const int32_t *lens, int n)
{
    memset(L, 0, sizeof(*L));
    L->n = n;
    L->m = n > 0 ? n : 1;
    L->lens = lens;
    size_t m = (size_t)L->m;
    L->pk = (u128 *)malloc(sizeof(u128) * m);
    L->nodes = (u128 *)malloc(sizeof(u128) * (size_t)MAXD * m);
    L->ncnt = (int *)calloc(MAXD, sizeof(int));
    L->byLenOff = (int *)calloc(MAXD + 1, sizeof(int));
    L->byLen = (int *)malloc(sizeof(int) * m);
    L->byLenCnt = (int *)calloc(MAXD, sizeof(int));
    if (!L->pk || !L->nodes || !L->ncnt || !L->byLenOff || !L->byLen || !L->byLenCnt) {
        layout_free(L);
        return -1;
    }
    for (int i = 0; i < n; i++) {
        L->pk[i].hi = addrs[2 * (size_t)i];
        L->pk[i].lo = addrs[2 * (size_t)i + 1];
        if (lens[i] < 0 || lens[i] > 128) { layout_free(L); return -1; }
        L->byLenCnt[lens[i]]++;
    }
    for (int d = 0; d < MAXD; d++) {
        u128 *dst = L->nodes + (size_t)d * m;
        int c = 0;
        if (d == 0) {
            dst[0].hi = 0; dst[0].lo = 0; c = 1;      /* the root always exists */
        } else if (d < 128) {
            for (int i = 0; i < n; i++)
                if (lens[i] > d) dst[c++] = trunc128(L->pk[i], d);
            qsort(dst, (size_t)c, sizeof(u128), cmp_u128);
            int w = 0;
            for (int i = 0; i < c; i++)
                if (i == 0 || cmp_u128(&dst[i], &dst[i - 1]) != 0) dst[w++] = dst[i];
            c = w;
        }
        L->ncnt[d] = c;
    }
    {
        int acc = 0;
        int *fill = (int *)malloc(sizeof(int) * MAXD);
        if (!fill) { layout_free(L); return -1; }
        for (int Lg = 0; Lg < MAXD; Lg++) { L->byLenOff[Lg] = acc; acc += L->byLenCnt[Lg]; fill[Lg] = L->byLenOff[Lg]; }
        L->byLenOff[MAXD] = acc;
        for (int i = 0; i < n; i++) L->byLen[fill[lens[i]]++] = i;
        free(fill);
    }
    return 0;
}

/* U[b*MAXD+e] = total codec bits of stage (b,e]; -1 when e-b>ms or e<=b */
static int compute_u(const layout_t *L, int ms, int64_t *U)
{
    int n = L->n, m = L->m;
    int64_t *Racc = (int64_t *)malloc(sizeof(int64_t) * (size_t)m);
    int *Ecnt = (int *)malloc(sizeof(int) * (size_t)m);
    if (!Racc || !Ecnt) { free(Racc); free(Ecnt); return -1; }
    for (size_t i = 0; i < (size_t)MAXD * MAXD; i++) U[i] = -1;
    for (int b = 0; b < 128; b++) {
        int cb = L->ncnt[b];
        for (int k = 0; k < cb; k++) Racc[k] = 0;
        if (b == 0 && L->byLenCnt[0] > 0) Racc[0] += 32;   /* the /0 rule */
        int emax = b + ms; if (emax > 128) emax = 128;
        for (int e = b + 1; e <= emax; e++) {
            int w = 32 + (int)align_up((uint64_t)(e - b), 8);
            for (int t = L->byLenOff[e]; t < L->byLenOff[e + 1]; t++) {
                int i = L->byLen[t];
                int idx;
                if (b == 0) {
                    idx = 0;
                } else {
                    u128 key = trunc128(L->pk[i], b);
                    const u128 *base = L->nodes + (size_t)b * m;
                    int lo = 0, hi = cb - 1;
                    idx = -1;
                    while (lo <= hi) {
                        int mid = (lo + hi) >> 1;
                        int c = cmp_u128(&base[mid], &key);
                        if (c == 0) { idx = mid; break; }
                        if (c < 0) lo = mid + 1; else hi = mid - 1;
                    }
                    if (idx < 0) continue;   /* impossible for a canonical layout */
                }
                Racc[idx] += w;
            }
            for (int k = 0; k < cb; k++) Ecnt[k] = 0;
            if (e < 128 && cb > 0) {
                int ce = L->ncnt[e];
                const u128 *bb = L->nodes + (size_t)b * m;
                const u128 *ee = L->nodes + (size_t)e * m;
                int k = 0, j = 0;
                while (k < cb && j < ce) {
                    u128 par = trunc128(ee[j], b);
                    int c = cmp_u128(&par, &bb[k]);
                    if (c == 0) { Ecnt[k]++; j++; }
                    else if (c > 0) { k++; }
                    else { j++; }
                }
            }
            uint64_t ew = (e < 128) ? (uint64_t)w : 0;
            uint64_t tot = 0;
            for (int k = 0; k < cb; k++)
                tot += align_up(128 + (uint64_t)Racc[k] + (uint64_t)Ecnt[k] * ew, 64);
            U[(size_t)b * MAXD + e] = (int64_t)tot;
        }
    }
    free(Racc); free(Ecnt);
    return 0;
}

/* debug/test export: dump the whole U table */
int utab(const uint64_t *addrs, const int32_t *lens, int n, int ms, int64_t *out)
{
    layout_t L;
    if (n < 0 || n > 8192 || ms < 1 || ms > 32) return -1;
    if (layout_build(&L, addrs, lens, n) != 0) return -1;
    int rc = compute_u(&L, ms, out);
    layout_free(&L);
    return rc;
}

/* ------------------------------------------------------------------ */
/* find_cuts                                                           */
/* ------------------------------------------------------------------ */

int find_cuts(const uint64_t *addrs, const int32_t *lens, int n,
              const int64_t *caps, int S, int ms,
              int32_t *out_cuts, int64_t *out_used,
              int64_t *out_num, int64_t *out_den)
{
    if (S < 4 || S > 16 || ms < 1 || ms > 32 || n < 0 || n > 8192) return -1;
    if (!addrs || !lens || !caps || !out_cuts || !out_used || !out_num || !out_den) return -1;
    for (int i = 0; i < S; i++) if (caps[i] <= 0 || caps[i] > 1000000000LL) return -1;

    layout_t L;
    if (layout_build(&L, addrs, lens, n) != 0) return -1;
    int rc = -1;
    int64_t *U = (int64_t *)malloc(sizeof(int64_t) * (size_t)MAXD * MAXD);
    int64_t *fnum = (int64_t *)malloc(sizeof(int64_t) * (size_t)(S + 1) * MAXD);
    int64_t *fden = (int64_t *)malloc(sizeof(int64_t) * (size_t)(S + 1) * MAXD);
    unsigned char *fok = (unsigned char *)calloc((size_t)(S + 1) * MAXD, 1);
    if (!U || !fnum || !fden || !fok) goto done;
    if (compute_u(&L, ms, U) != 0) goto done;

    for (int d = 0; d < MAXD; d++) fok[(size_t)S * MAXD + d] = 0;
    fnum[(size_t)S * MAXD + 128] = 0;
    fden[(size_t)S * MAXD + 128] = 1;
    fok[(size_t)S * MAXD + 128] = 1;
    for (int i = S - 1; i >= 0; i--) {
        for (int d = 0; d < MAXD; d++) {
            fok[(size_t)i * MAXD + d] = 0;
            fnum[(size_t)i * MAXD + d] = 0;
            fden[(size_t)i * MAXD + d] = 1;
        }
        for (int d = 0; d < 128; d++) {
            int have = 0;
            int64_t bn = 0, bd = 1;
            int emax = d + ms; if (emax > 128) emax = 128;
            for (int e = d + 1; e <= emax; e++) {
                if (!fok[(size_t)(i + 1) * MAXD + e]) continue;
                int64_t u = U[(size_t)d * MAXD + e];
                if (u < 0) continue;
                int64_t cn = u, cd = caps[i];
                int64_t fn = fnum[(size_t)(i + 1) * MAXD + e];
                int64_t fd = fden[(size_t)(i + 1) * MAXD + e];
                if (rat_less(cn, cd, fn, fd)) { cn = fn; cd = fd; }
                if (!have || rat_less(cn, cd, bn, bd)) { have = 1; bn = cn; bd = cd; }
            }
            if (have) {
                fok[(size_t)i * MAXD + d] = 1;
                fnum[(size_t)i * MAXD + d] = bn;
                fden[(size_t)i * MAXD + d] = bd;
            }
        }
    }

    if (!fok[0]) { rc = 1; goto done; }
    {
        int64_t pn = fnum[0], pd = fden[0];
        if (pn > pd) { rc = 1; goto done; }     /* peak > 1 => infeasible */
        int d = 0;
        out_cuts[0] = 0;
        for (int i = 0; i < S; i++) {
            int emax = d + ms; if (emax > 128) emax = 128;
            int chosen = -1;
            int64_t tn = fnum[(size_t)i * MAXD + d], td = fden[(size_t)i * MAXD + d];
            for (int e = d + 1; e <= emax; e++) {
                if (!fok[(size_t)(i + 1) * MAXD + e]) continue;
                int64_t u = U[(size_t)d * MAXD + e];
                if (u < 0) continue;
                int64_t cn = u, cd = caps[i];
                int64_t fn = fnum[(size_t)(i + 1) * MAXD + e];
                int64_t fd = fden[(size_t)(i + 1) * MAXD + e];
                if (rat_less(cn, cd, fn, fd)) { cn = fn; cd = fd; }
                if (cn == tn && cd == td) { chosen = e; break; }
            }
            if (chosen < 0) { rc = -1; goto done; }
            out_cuts[i + 1] = chosen;
            out_used[i] = U[(size_t)d * MAXD + chosen];
            d = chosen;
        }
        {
            int64_t a = pn, b = pd, t;
            if (a == 0) { *out_num = 0; *out_den = 1; }
            else {
                while (b) { t = a % b; a = b; b = t; }
                *out_num = pn / a;
                *out_den = pd / a;
            }
        }
        rc = 0;
    }

done:
    free(U); free(fnum); free(fden); free(fok);
    layout_free(&L);
    return rc;
}

/* ------------------------------------------------------------------ */
/* lpm_batch                                                           */
/* ------------------------------------------------------------------ */

static const uint64_t *g_hi, *g_lo;
static const int32_t *g_len;

static int cmp_idx(const void *pa, const void *pb)
{
    int a = *(const int *)pa, b = *(const int *)pb;
    if (g_len[a] != g_len[b]) return g_len[a] < g_len[b] ? 1 : -1;
    if (g_hi[a] != g_hi[b]) return g_hi[a] < g_hi[b] ? -1 : 1;
    if (g_lo[a] != g_lo[b]) return g_lo[a] < g_lo[b] ? -1 : 1;
    return 0;
}

int lpm_batch(const uint64_t *rhi, const uint64_t *rlo, const int32_t *rlen,
              const int32_t *rhop, int nr,
              const uint64_t *qhi, const uint64_t *qlo, int nq,
              int32_t *out_hop, int32_t *out_plen)
{
    if (nr < 0 || nq < 0) return -1;
    int *idx = (int *)malloc(sizeof(int) * (size_t)(nr > 0 ? nr : 1));
    int *cnt = (int *)calloc(MAXD, sizeof(int));
    int *off = (int *)calloc(MAXD + 1, sizeof(int));
    if (!idx || !cnt || !off) { free(idx); free(cnt); free(off); return -1; }
    for (int i = 0; i < nr; i++) {
        if (rlen[i] < 0 || rlen[i] > 128) { free(idx); free(cnt); free(off); return -1; }
        idx[i] = i; cnt[rlen[i]]++;
    }
    g_hi = rhi; g_lo = rlo; g_len = rlen;
    if (nr > 1) qsort(idx, (size_t)nr, sizeof(int), cmp_idx);
    int acc = 0;
    for (int L = MAXD - 1; L >= 0; L--) { off[L] = acc; acc += cnt[L]; }
    off[MAXD] = acc;
    for (int q = 0; q < nq; q++) {
        u128 a; a.hi = qhi[q]; a.lo = qlo[q];
        int found = 0; int32_t fh = 0, fl = 0;
        for (int L = 128; L >= 0; L--) {
            if (cnt[L] == 0) continue;
            u128 key = trunc128(a, L);
            int lo = off[L], hi = off[L] + cnt[L] - 1;
            while (lo <= hi) {
                int mid = (lo + hi) >> 1;
                int r = idx[mid];
                if (rhi[r] < key.hi) lo = mid + 1;
                else if (rhi[r] > key.hi) hi = mid - 1;
                else if (rlo[r] < key.lo) lo = mid + 1;
                else if (rlo[r] > key.lo) hi = mid - 1;
                else { found = 1; fh = rhop[r]; fl = L; break; }
            }
            if (found) break;
        }
        if (found) { out_hop[q] = fh; out_plen[q] = fl; }
        else { out_hop[q] = -1; out_plen[q] = -1; }
    }
    free(idx); free(cnt); free(off);
    return 0;
}
EOF
cd /app/submit && gcc -O2 -std=gnu11 -Wall -Wextra -fPIC -shared -o /app/tmp/helper.so helper.c && echo BUILD_OK && cd /app && python3 public_sanity.py
